/**
 * 「must be 允许集」/ `Cannot pass a value of type` / Object 位这三族形参拒的两侧：每一格都是 `tmp/probe-argtype/matrix.mts`
 * 往那一位塞那一种字面量、其余位给合法填充量到的引擎原文（`tmp/probe-argtype/matrix.txt`），句子逐字钉；
 * 收的那一侧是「不许误拦」—— 同一位上引擎放过的那些形（`abs([])`、`abs(Vector2(1, 2))`、`inst_to_dict(null)`）全部留在门里。
 */
import { describe, expect, it } from "vitest";
import { analyze } from "@gds2js/compiler/lower/analyze";
import { lower } from "@gds2js/compiler/lower/lower";
import { parseSource } from "@gds2js/compiler/parse/parser";

const diags = async (src: string): Promise<string[]> => {
  const tree = await parseSource(`extends SceneTree\n\nfunc _initialize():\n\tvar v = ${src}\n\tprint("X||", v)\n\tquit()\n`);
  return analyze(lower(tree)).diagnostics.map((d) => d.message);
};

